exec(open('lib7.py',encoding='utf-8').read())
c='p9';B='SQL 4A'
def Q(tag,title,q,desc,note,db='thuexe',fs=20,ofs=20,ch='Ý chính'):
    o=SQLRUN(DBSETUP(db),q)
    return S2(c,B+' · '+tag,title,card(ch,P(*desc.split('<br>')))+CODE(PRETTY(q),fs),RES(OUT(o,ofs),'Kết quả chạy SQL')+(KEY(note) if note else ''))
M='mymusic_hsg'
S=[]
S.append(TITLE('TIN HỌC · SQL 4A','LIÊN KẾT BẢNG<br>VỚI JOIN','Vì sao phải JOIN, INNER JOIN … ON, bí danh bảng, nối ba bảng, JOIN kết hợp GROUP BY, LEFT JOIN, lỗi thiếu ON, cột trùng tên; dữ liệu mymusic và thuexe lấy từ đề.',['JOIN … ON','bí danh','3 bảng','LEFT JOIN','GROUP BY']))
S.append(goals(c,B,['Hiểu <b>khoá ngoài</b> liên kết các bảng và vì sao cần <b>JOIN</b>.','Viết <b>INNER JOIN … ON</b> đúng điều kiện nối; dùng <b>bí danh</b>.','Nối <b>ba bảng</b> (ví dụ bannhac – nhacsi, banthuam – bannhac – casi).','Kết hợp <b>JOIN + WHERE + GROUP BY + HAVING + ORDER BY</b>.','Phân biệt <b>INNER JOIN</b> và <b>LEFT JOIN</b>; tránh lỗi thiếu ON.'],['JOIN','Nối ba bảng','JOIN + nhóm','LEFT JOIN, lỗi','Tự kiểm tra']))
S.append(S2(c,B+' · 0','CSDL mymusic: bốn bảng',card('Khoá chính và khoá ngoài',P('<b>nhacsi</b>(idNhacsi, tenNhacsi); <b>casi</b>(idCasi, tenCasi).','<b>bannhac</b>(idBannhac, tenBannhac, <b>idNhacsi</b>→nhacsi).','<b>banthuam</b>(idBanthuam, <b>idBannhac</b>→bannhac, <b>idCasi</b>→casi): ai hát bản nhạc nào.','Bản thu âm là bảng <b>trung gian</b> cho quan hệ nhiều–nhiều giữa bản nhạc và ca sĩ.')),TBL(M,'bannhac',15)+TBL(M,'banthuam',15,limit=10)))
S.append(S2(c,B+' · 1','Vì sao phải JOIN?',card('Dữ liệu nằm rải rác nhiều bảng',P('Bảng <b>bannhac</b> chỉ lưu <b>idNhacsi</b> (số), không lưu <b>tên</b> nhạc sĩ.','Muốn hiển thị “tên bản nhạc – tên nhạc sĩ” phải <b>nối</b> bannhac với nhacsi theo <b>khoá ngoài = khoá chính</b>.')),RES(OUT(RESQ(M,'SELECT * FROM bannhac LIMIT 3'),22),'Chỉ có mã nhạc sĩ')+KEY('JOIN ghép dòng của hai bảng khi <b>giá trị khoá ngoài = giá trị khoá chính</b>.')))
S.append(Q('1','INNER JOIN … ON','SELECT b.tenBannhac, n.tenNhacsi FROM bannhac b INNER JOIN nhacsi n ON b.idNhacsi = n.idNhacsi','<b>FROM bảng1 JOIN bảng2 ON điều kiện nối</b>.<br><b>b</b>, <b>n</b> là <b>bí danh</b> bảng, giúp viết ngắn và <b>phân biệt cột trùng tên</b>.','INNER JOIN chỉ giữ cặp dòng <b>khớp điều kiện ON</b>.',M,fs=18,ofs=17,ch='Cú pháp'))
S.append(Q('1','Lọc theo tên (không viết thẳng mã)',"SELECT COUNT(*) AS SoBanNhac FROM bannhac b JOIN nhacsi n ON b.idNhacsi = n.idNhacsi WHERE n.tenNhacsi = 'Văn Cao'",'Đề: “Đếm số bản nhạc của Văn Cao (<b>viết theo tên</b> nhạc sĩ, không viết thẳng mã)”.<br>Tên chỉ có ở nhacsi → JOIN rồi WHERE theo tên.','Không viết <code>idNhacsi = 2</code> vì đề yêu cầu dùng tên.',M,fs=17,ch='Dùng tên thay mã'))
S.append(S2(c,B+' · 1','Tên cột trùng: phải có bí danh hoặc tên bảng',card('Cột không rõ ràng',P('Cả bannhac và nhacsi đều có cột <b>idNhacsi</b>: viết trần sẽ báo lỗi “ambiguous”.','Quy tắc: viết <b>bảng.cột</b> hoặc <b>bí danh.cột</b> cho mọi cột khi có JOIN.')),CODE('-- LỖI: không biết idNhacsi của bảng nào\nSELECT idNhacsi FROM bannhac b\nJOIN nhacsi n ON b.idNhacsi = n.idNhacsi;\n\n-- ĐÚNG\nSELECT n.idNhacsi FROM bannhac b\nJOIN nhacsi n ON b.idNhacsi = n.idNhacsi;',18)+RES(OUT(SQLRUN(DBSETUP(M),'SELECT idNhacsi FROM bannhac b JOIN nhacsi n ON b.idNhacsi = n.idNhacsi'),18),'Kết quả chạy câu bị lỗi')+KEY('Luôn đặt <b>bí danh</b> và viết <b>bí_danh.cột</b> trong câu có JOIN.')))
S.append(Q('2','Nối ba bảng: bản nhạc – ca sĩ','SELECT bn.tenBannhac, cs.tenCasi FROM banthuam bt JOIN bannhac bn ON bt.idBannhac = bn.idBannhac JOIN casi cs ON bt.idCasi = cs.idCasi ORDER BY bn.tenBannhac, cs.tenCasi','Nối <b>banthuam</b> với bannhac (lấy tên bản nhạc) rồi với casi (lấy tên ca sĩ): <b>mỗi JOIN có một ON</b>.<br>Sắp xếp theo hai cột.','Nối 3 bảng cần <b>2 điều kiện ON</b>.',M,fs=15,ofs=17,ch='Hai JOIN liên tiếp'))
S.append(S2(c,B+' · 2','Sơ đồ nối ba bảng',card('Đi theo khoá ngoài',STEPS(['banthuam.<b>idBannhac</b> = bannhac.<b>idBannhac</b>.','banthuam.<b>idCasi</b> = casi.<b>idCasi</b>.','Nối đủ để có <b>tên bản nhạc</b> và <b>tên ca sĩ</b> cùng một dòng.'])),'<svg viewBox="0 0 520 220" style="width:100%"><g font-family="sans-serif" font-weight="800" font-size="20"><rect x="10" y="80" width="130" height="60" rx="8" fill="#BBDEFB" stroke="#1565C0" stroke-width="3"/><text x="75" y="118" text-anchor="middle" fill="#0B2545">bannhac</text><rect x="195" y="80" width="130" height="60" rx="8" fill="#FFF9C4" stroke="#F9A825" stroke-width="3"/><text x="260" y="118" text-anchor="middle" fill="#0B2545">banthuam</text><rect x="380" y="80" width="130" height="60" rx="8" fill="#C8E6C9" stroke="#2E7D32" stroke-width="3"/><text x="445" y="118" text-anchor="middle" fill="#0B2545">casi</text><line x1="140" y1="110" x2="195" y2="110" stroke="#C62828" stroke-width="4"/><line x1="325" y1="110" x2="380" y2="110" stroke="#C62828" stroke-width="4"/><text x="167" y="70" text-anchor="middle" font-size="15" fill="#C62828">idBannhac</text><text x="352" y="70" text-anchor="middle" font-size="15" fill="#C62828">idCasi</text></g></svg>'+KEY('Bảng ở giữa (<b>banthuam</b>) chứa <b>hai khoá ngoài</b>: là cầu nối.')))
S.append(Q('2','JOIN + GROUP BY: tổng số bản thu âm của mỗi nhạc sĩ','SELECT n.tenNhacsi, COUNT(*) AS SoBanThuAm FROM nhacsi n JOIN bannhac bn ON bn.idNhacsi = n.idNhacsi JOIN banthuam bt ON bt.idBannhac = bn.idBannhac GROUP BY n.idNhacsi, n.tenNhacsi ORDER BY SoBanThuAm DESC, n.tenNhacsi','“Với mỗi nhạc sĩ, cho biết tên và tổng số bản thu âm của các bản nhạc do nhạc sĩ đó sáng tác”.<br>Nối 3 bảng, <b>nhóm theo nhạc sĩ</b>, đếm.','Nhóm theo <b>khoá (idNhacsi)</b> và tên để tránh gộp nhầm hai người trùng tên.',M,fs=14,ofs=18,ch='Nhóm sau khi nối'))
S.append(Q('2','JOIN + WHERE: nhạc sĩ có bản nhạc do Quốc Hương hát',"SELECT DISTINCT n.tenNhacsi FROM nhacsi n JOIN bannhac bn ON bn.idNhacsi = n.idNhacsi JOIN banthuam bt ON bt.idBannhac = bn.idBannhac JOIN casi cs ON cs.idCasi = bt.idCasi WHERE cs.tenCasi = 'Quốc Hương'",'Nối cả <b>bốn bảng</b>, lọc tên ca sĩ, <b>DISTINCT</b> để mỗi nhạc sĩ một lần.','Không có DISTINCT, nhạc sĩ có nhiều bản do Quốc Hương hát bị lặp.',M,fs=14,ofs=20,ch='Nối bốn bảng'))
S.append(Q('2','JOIN trên thuexe: ba bảng, nhiều điều kiện',"SELECT k.MaKT, k.TenKT, SUM(l.SoGio) AS TongGio FROM KhachThue k JOIN LuotThue l ON k.MaKT = l.MaKT JOIN PhuongTien p ON p.MaPT = l.MaPT WHERE p.LoaiPT = 'Xe điện' AND l.Tram = 'DN01' AND l.NgayThue LIKE '2026%' GROUP BY k.MaKT, k.TenKT HAVING SUM(l.SoGio) >= 6",'Mẫu của đề: <b>nối bảng → WHERE từng lượt → GROUP BY khách → HAVING tổng</b>.','Nhóm theo <b>MaKT (khoá chính)</b>; có thêm TenKT để hiển thị.',fs=13,ofs=20,ch='Mẫu HSG'))
S.append(TB(c,B+' · 3','INNER JOIN và LEFT JOIN',['','INNER JOIN','LEFT JOIN'],[['<b>Giữ dòng nào?</b>','chỉ dòng có <b>cặp khớp</b> ở cả hai bảng','<b>mọi dòng bảng trái</b>; không khớp thì cột bên phải là <b>NULL</b>'],['<b>Dùng khi</b>','chỉ quan tâm dữ liệu có liên kết','cần liệt kê cả đối tượng <b>chưa có</b> liên kết (khách chưa thuê)'],['<b>Ví dụ</b>','khách đã có lượt thuê','khách chưa từng thuê']],note=KEY('Tìm đối tượng “<b>chưa từng</b> …” → <b>LEFT JOIN … WHERE cột_bên_phải IS NULL</b>.')))
S.append(Q('3','LEFT JOIN: khách chưa từng thuê','SELECT k.MaKT, k.TenKT FROM KhachThue k LEFT JOIN LuotThue l ON k.MaKT = l.MaKT WHERE l.MaLuot IS NULL','K006 (Khoa) không có lượt thuê nào: LEFT JOIN giữ lại dòng của Khoa, các cột của LuotThue là NULL, rồi lọc <b>IS NULL</b>.','INNER JOIN sẽ <b>làm mất</b> khách này.',fs=18,ch='Mẫu “chưa từng”'))
S.append(S2(c,B+' · 3','Lỗi kinh điển: JOIN thiếu điều kiện ON',card('Tích Descartes',P('Thiếu <b>ON</b> (hoặc nối sai cột) → mỗi dòng bảng 1 ghép <b>với mọi dòng</b> bảng 2.','KhachThue 6 dòng × LuotThue 12 dòng = <b>72</b> dòng vô nghĩa.')),RES(OUT(SQLRUN(DBSETUP('thuexe'),'SELECT COUNT(*) AS so_dong FROM KhachThue CROSS JOIN LuotThue'),26),'Số dòng khi không có điều kiện nối')+CODE('SELECT COUNT(*) FROM KhachThue\nCROSS JOIN LuotThue;       -- 72\n\nSELECT COUNT(*) FROM KhachThue k\nJOIN LuotThue l ON k.MaKT = l.MaKT; -- 12',19)+KEY('Số dòng sau JOIN <b>vượt xa</b> dự kiến → kiểm tra lại <b>ON</b>.')))
S.append(SELF(c,B+' · 4','Tự kiểm tra 1: viết điều kiện nối','Viết câu liệt kê tên bản nhạc và tên nhạc sĩ của bản nhạc đó.','',P('<code>SELECT b.tenBannhac, n.tenNhacsi FROM bannhac b JOIN nhacsi n ON b.idNhacsi = n.idNhacsi;</code>','Điều kiện nối: <b>khoá ngoài = khoá chính</b>.'),20))
S.append(SELF(c,B+' · 4','Tự kiểm tra 2: dự đoán kết quả',"Không chạy máy, dự đoán số dòng kết quả.","SELECT k.TenKT, l.SoGio\nFROM KhachThue k\nJOIN LuotThue l ON k.MaKT = l.MaKT;",P('Mỗi lượt thuê khớp đúng một khách → <b>12</b> dòng (bằng số lượt thuê). Khách K006 không có lượt nên không xuất hiện.','Chạy thật: <b>%s</b> dòng.'%SQL1('SELECT COUNT(*) FROM KhachThue k JOIN LuotThue l ON k.MaKT=l.MaKT',DBSETUP('thuexe'))),20))
S.append(SELF(c,B+' · 4','Tự kiểm tra (HSG): đúng hay sai?','(a) INNER JOIN giữ dòng không khớp. (b) LEFT JOIN giữ mọi dòng bảng trái. (c) Nối 3 bảng cần 2 điều kiện ON. (d) Thiếu ON cho tích Descartes. (e) Khi có JOIN, cột trùng tên phải viết kèm bí danh.','',P('(a) <b>Sai</b>: chỉ giữ dòng khớp.','(b) <b>Đúng</b>.','(c) <b>Đúng</b>.','(d) <b>Đúng</b>.','(e) <b>Đúng</b>.'),20))
S+=END(c,B,['<b>JOIN … ON khoá ngoài = khoá chính</b> ghép các bảng.','Dùng <b>bí danh</b>, viết <b>bí_danh.cột</b>.','Nối n bảng cần <b>n−1 điều kiện ON</b>.','JOIN + WHERE → GROUP BY → HAVING → ORDER BY.','“Chưa từng” → <b>LEFT JOIN … IS NULL</b>; thiếu ON → tích Descartes.'],[('Nối hai bảng','JOIN … ON'),('Giữ mọi dòng trái','LEFT JOIN'),('Mỗi nhạc sĩ một lần','DISTINCT / GROUP BY'),('Chưa từng','LEFT JOIN … IS NULL')],'Thiếu ON; cột trùng tên không bí danh; dùng INNER JOIN khi cần LEFT JOIN; nhóm theo tên thay vì khoá.',['<b>USING(cột)</b> khi tên cột giống nhau.','<b>NATURAL JOIN</b> nên tránh.','<b>Self join</b>.'],['<b>RIGHT/FULL JOIN</b>.','Thứ tự JOIN và hiệu năng.','<b>EXISTS</b> thay LEFT JOIN … IS NULL.'],
 [('Điều kiện nối thường là?',),('Giữ mọi dòng bảng trái?',),('Số điều kiện ON khi nối 4 bảng?',),('Lỗi khi thiếu ON?',),('Liệt kê khách chưa từng thuê?',)],
 [('<b>khoá ngoài = khoá chính</b>.',),('<b>LEFT JOIN</b>.',),('<b>3</b>.',),('<b>Tích Descartes</b>.',),('<b>LEFT JOIN … WHERE … IS NULL</b>.',)],
 [('Mức 1. Liệt kê tên bản nhạc và tên nhạc sĩ.',),('Mức 1. Liệt kê MaLuot và LoaiPT của mọi lượt thuê.',),('Mức 2. Tên bản nhạc và tên ca sĩ, sắp theo tên bản nhạc rồi ca sĩ.',),('Mức 2. Tổng giờ mỗi loại phương tiện.',),('Mức 3 (HSG). Với mỗi ca sĩ, số bản nhạc KHÁC NHAU đã thể hiện.',),('Mức 3 (HSG). Khách chưa từng thuê xe điện.',)],
 [('JOIN bannhac, nhacsi.',),('JOIN LuotThue, PhuongTien.',),('JOIN 3 bảng + ORDER BY 2 cột.',),('GROUP BY LoaiPT với SUM(SoGio).',),('COUNT(DISTINCT idBannhac) GROUP BY ca sĩ.',),('NOT IN / LEFT JOIN điều kiện loại xe điện.',)],hper=2)
mkdeck('c4a.html','SQL 4A · Liên kết bảng với JOIN',S)
